<script setup lang="ts">
import {onMounted,ref,reactive,computed} from 'vue'
import MainLayout from '@/components/MainLayout.vue'
import QueryTable from '@/components/QueryTable.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
type Row=Record<string,any>
const auth=useAuthStore(),tab=ref('chat'),question=ref(''),session=ref(''),busy=ref(false),error=ref(''),config=ref<Row>({}),catalog=ref<Row>({materials:[],warehouses:[],products:[]}),answer=ref<Row>(),history=ref<Row[]>([]),messages=ref<{question:string;reply:Row}[]>([])
const form=reactive<Row>({kind:'INVENTORY',material:'',warehouse:'',type:'',product:'',from:'',to:'',document:''})
const canInventory=computed(()=>[1,2,5,6,9,10].includes(Number(auth.currentUser?.roleId)))
const examples=['本月原材料库存','当前缺料和安全库存','改查上个月','只看原料仓']
const labels:Row={kind:'查询类型',material:'物料ID',warehouse:'仓库ID',product:'产品ID',type:'物料类别',from:'开始日期',to:'结束日期',document:'单据编号'}
async function load(){try{config.value=await request.get('/ai/config');history.value=await request.get('/ai/history');if(canInventory.value)catalog.value=await request.get('/analytics/catalog');else form.kind='TRACE'}catch(e:any){error.value=e.message}}
async function ask(){if(!question.value.trim()||busy.value)return;busy.value=true;error.value='';try{const q=question.value;const r=await request.post<Row>('/ai/query',{question:q,...(session.value?{sessionId:session.value}:{})});session.value=r.sessionId;messages.value.push({question:q,reply:r});answer.value=r.result;question.value='';history.value=await request.get('/ai/history')}catch(e:any){error.value=e.message;answer.value=undefined}finally{busy.value=false}}
async function manual(){busy.value=true;error.value='';try{const f=Object.fromEntries(Object.entries(form).filter(([k,v])=>v!==''&&(form.kind==='TRACE'?['kind','document'].includes(k):k!=='document'&&(form.kind!=='SHORTAGE'||!['from','to'].includes(k)))));answer.value=await request.post('/analytics/query',f)}catch(e:any){error.value=e.message;answer.value=undefined}finally{busy.value=false}}
function reset(){session.value='';messages.value=[];answer.value=undefined;error.value=''}
onMounted(load)
</script>
<template><MainLayout><div class="max-w-7xl mx-auto space-y-5"><div class="flex justify-between"><div><p class="text-blue-600 text-sm">MES 数据助手</p><h1 class="text-2xl font-bold mt-1">智能业务查询</h1><p class="text-slate-500 mt-2 text-sm">真实库存、缺料和单据追溯，保留条件与来源以便人工复核。</p></div><router-link to="/dashboard" class="text-blue-600">生产看板 →</router-link></div>
<p class="bg-blue-50 rounded-lg p-4 text-sm">{{config.mode==='remote'?'远程模型解析':'本地规则解析（未调用大模型）'}} · {{config.mode==='remote'?(config.configured?'接口已配置，实际调用状态见查询记录':'接口未配置'): '本地查询不消耗模型 Token'}}。远程模式每人每天最多20次，单次输出上限512 Token。</p>
<div class="flex gap-2"><button class="px-4 py-2 rounded border" :class="{'bg-blue-600 text-white':tab==='chat'}" @click="tab='chat'">自然语言</button><button class="px-4 py-2 rounded border" :class="{'bg-blue-600 text-white':tab==='form'}" @click="tab='form'">人工条件核对</button></div>
<section v-if="tab==='chat'" class="bg-white border rounded-xl p-5 space-y-4"><div class="flex justify-between"><h2 class="font-semibold">查询会话</h2><button @click="reset" class="text-blue-600 text-sm">新会话</button></div><div class="flex flex-wrap gap-2"><button v-for="e in examples" :key="e" class="text-xs rounded-full bg-slate-100 px-3 py-2" @click="question=e">{{e}}</button></div><p class="text-sm text-slate-500">可延续上一轮条件；物料或仓库含多个匹配时请用“物料：精确名称”“仓库：精确名称”补充。</p>
<div v-for="(m,i) in messages" :key="i" class="border rounded-lg p-4 space-y-2"><p class="font-medium">{{m.question}}</p><p v-for="c in m.reply.clarifications" :key="c" class="text-amber-700">{{c}}</p><p class="text-sm">{{m.reply.result?'已完成查询，结果见下方。':'等待补充条件。'}}</p><p class="text-xs text-slate-500 break-all">条件：{{m.reply.conditions}} · 编号 {{m.reply.traceId}} · Token {{m.reply.inputTokens}} / {{m.reply.outputTokens}}</p></div>
<form @submit.prevent="ask" class="flex gap-3"><input v-model="question" maxlength="1200" placeholder="例如：查询本月原材料库存，或追溯 MO-完整工单号" class="flex-1 border rounded-lg px-4 py-3" aria-label="查询问题"><button :disabled="busy" class="bg-blue-600 text-white px-6 rounded-lg disabled:opacity-50">{{busy?'正在查询…':'查询'}}</button></form></section>
<form v-else @submit.prevent="manual" class="bg-white border rounded-xl p-5 grid sm:grid-cols-3 gap-4"><label>查询类型<select v-model="form.kind" class="block border rounded p-2 w-full"><option v-if="canInventory" value="INVENTORY">库存与出入库</option><option v-if="canInventory" value="SHORTAGE">当前缺料</option><option value="TRACE">工单/订单/计划追溯</option></select></label><template v-if="form.kind!=='TRACE'"><label>物料<select v-model="form.material" class="block border rounded p-2 w-full"><option value="">全部物料</option><option v-for="m in catalog.materials" :key="m.id" :value="String(m.id)">{{m.material_code}} {{m.material_name}}</option></select></label><label>仓库<select v-model="form.warehouse" class="block border rounded p-2 w-full"><option value="">全部仓库</option><option v-for="w in catalog.warehouses" :key="w.id" :value="String(w.id)">{{w.warehouse_name}}</option></select></label><label>物料类别<select v-model="form.type" class="block border rounded p-2 w-full"><option value="">全部类别</option><option value="1">原材料</option><option value="2">半成品</option><option value="3">成品</option></select></label><label>产品<select v-model="form.product" class="block border rounded p-2 w-full"><option value="">全部产品</option><option v-for="p in catalog.products" :key="p.id" :value="String(p.id)">{{p.product_name}}</option></select></label><template v-if="form.kind==='INVENTORY'"><label>开始日期<input v-model="form.from" type="date" class="block border rounded p-2 w-full"></label><label>结束日期<input v-model="form.to" type="date" class="block border rounded p-2 w-full"></label></template></template><label v-else>完整单据编号<input v-model="form.document" required class="block border rounded p-2 w-full"></label><button :disabled="busy" class="bg-blue-600 text-white rounded p-2 self-end">执行相同口径查询</button></form>
<p v-if="error" role="alert" class="bg-red-50 text-red-700 p-4 rounded">{{error}}</p>
<section v-if="answer" class="bg-white border rounded-xl p-5 space-y-4"><h2 class="font-semibold text-lg">查询结果</h2><p class="text-sm text-slate-600">{{answer.evidence}}</p><p class="text-xs text-slate-500">更新：{{answer.updatedAt}}；可信基线：{{answer.baselineAt||'不适用'}}。日期包含首尾两日；数量单位逐行显示。</p><dl class="flex flex-wrap gap-3 text-sm"><div v-for="(v,k) in answer.conditions" :key="k" class="bg-slate-100 px-3 py-1 rounded">{{labels[k]||k}}：{{v}}</div></dl><QueryTable :rows="answer.rows||[]"/><template v-if="answer.reports"><h3 class="font-semibold">报工记录</h3><QueryTable :rows="answer.reports"/><h3 class="font-semibold">过程检验</h3><QueryTable :rows="answer.inspections||[]"/></template><h3 class="font-semibold">来源库存流水（最新200条）</h3><QueryTable :rows="(answer.sources||[]).slice(0,200)"/><p v-if="answer.sources?.length>200" class="text-amber-700">来源记录较多，请缩小查询条件查看完整明细。</p></section>
<details class="bg-white border rounded p-4"><summary>最近查询与用量</summary><div class="overflow-auto"><table class="text-sm w-full"><tr class="text-left"><th>问题</th><th>模式</th><th>状态</th><th>输入/输出 Token</th><th>耗时</th></tr><tr v-for="h in history" :key="h.id" class="border-t"><td class="py-2">{{h.question}}</td><td>{{h.mode}}</td><td>{{h.status}}</td><td>{{h.input_tokens}} / {{h.output_tokens}}</td><td>{{h.elapsed_ms}} ms</td></tr></table></div></details></div></MainLayout></template>
